import{_ as s,C as l,o as a,c as i,a2 as o,b as n,w as t,a as d,E as u,a3 as c}from"./chunks/framework.CZGNF-7T.js";const p=JSON.parse('{"title":"업무 관리 (Issues/Tasks)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/issue.md","filePath":"work-manage/issue.md","lastUpdated":1788523110000}'),E={name:"work-manage/issue.md"};function h(g,e,C,B,m,A){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="업무-관리-issues-tasks" tabindex="-1">업무 관리 (Issues/Tasks) <a class="header-anchor" href="#업무-관리-issues-tasks" aria-label="Permalink to &quot;업무 관리 (Issues/Tasks)&quot;">​</a></h1><blockquote><p><strong>업무 관리</strong> 모듈은 부동산 개발 및 본사 관리 과정에서 발생하는 모든 실무 과업을 &#39;티켓(Ticket)&#39; 단위로 등록하고, 담당자·일정·진척률 및 의사결정 맥락을 체계적으로 추적하는 IBS의 핵심 협업 시스템입니다.</p></blockquote><h2 id="_1-개요-및-2대-진입-경로" tabindex="-1">1. 개요 및 2대 진입 경로 <a class="header-anchor" href="#_1-개요-및-2대-진입-경로" aria-label="Permalink to &quot;1. 개요 및 2대 진입 경로&quot;">​</a></h2><p>업무 시스템은 사용자의 작업 컨텍스트에 따라 두 가지 경로로 접근할 수 있습니다.</p><ul><li><strong>전사 통합 업무</strong>: 상단 메인 메뉴의 **[업무]**를 통해 진입하며, 본인이 권한을 가진 모든 워크스페이스의 업무를 통합 모니터링합니다.</li><li><strong>워크스페이스별 업무</strong>: 특정 워크스페이스 내의 <strong>[업무]</strong> 탭으로 진입하여 해당 사업지나 부서에 국한된 작업에 집중합니다.</li></ul>',5)),(a(),n(c,null,{default:t(()=>[u(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%93%9D%20%EC%97%85%EB%AC%B4%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%EC%9C%A0%ED%98%95%C2%B7%EC%9A%B0%EC%84%A0%EC%88%9C%EC%9C%84%C2%B7%EB%8B%B4%EB%8B%B9%EC%9E%90)%22%5D%20--%3E%20B%5B%22%E2%9B%93%EF%B8%8F%20%EA%B5%AC%EC%A1%B0%ED%99%94%20%26%20%EC%97%B0%EB%8F%99%3Cbr%3E(%ED%95%98%EC%9C%84%EC%97%85%EB%AC%B4%C2%B7%EC%84%A0%ED%9B%84%ED%96%89%C2%B7%ED%9A%8C%EC%9D%98%EB%A1%9D)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%92%AC%20%EC%A7%84%ED%96%89%20%26%20%ED%98%91%EC%97%85%3Cbr%3E(%EB%8C%93%EA%B8%80%C2%B7%ED%8C%8C%EC%9D%BC%C2%B7%EC%A7%84%EC%B2%99%EB%A5%A0%20%EA%B0%B1%EC%8B%A0)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8A%20%EC%9D%B4%EB%A0%A5%20%EC%B6%94%EC%A0%81%20%26%20%EB%B3%B4%EA%B3%A0%EC%84%9C%3Cbr%3E(Diff%20%EC%9D%B4%EB%A0%A5%C2%B7%EB%A7%88%EC%9D%BC%EC%8A%A4%ED%86%A4%20%EC%A7%91%EA%B3%84)%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="_2-업무-목록-및-생산성-도구" tabindex="-1">2. 업무 목록 및 생산성 도구 <a class="header-anchor" href="#_2-업무-목록-및-생산성-도구" aria-label="Permalink to &quot;2. 업무 목록 및 생산성 도구&quot;">​</a></h2><p>수많은 업무 속에서 필요한 데이터를 즉시 추출할 수 있도록 강력한 그리드 도구를 제공합니다.</p><h3 id="🔍-다차원-필터링-및-검색" tabindex="-1">🔍 다차원 필터링 및 검색 <a class="header-anchor" href="#🔍-다차원-필터링-및-검색" aria-label="Permalink to &quot;🔍 다차원 필터링 및 검색&quot;">​</a></h3><ul><li><strong>상태 필터</strong>: &#39;진행 중(Open)&#39; 업무만 보거나, &#39;종료(Closed)&#39;된 업무를 포함한 전체 업무를 원클릭 전환합니다.</li><li><strong>조건 조합</strong>: 업무 유형(Tracker), 우선순위, 담당자, 작성자, 범주(Category), 목표 단계(Version)를 자유롭게 조합하여 필터링합니다.</li><li><strong>내 업무 모아보기</strong>: 담당자가 &#39;나&#39;로 지정된 업무를 우선 배치하여 당일 처리해야 할 업무 우선순위를 빠르게 판단할 수 있습니다.</li></ul><h3 id="📋-컬럼-커스터마이징-column-selector" tabindex="-1">📋 컬럼 커스터마이징 (Column Selector) <a class="header-anchor" href="#📋-컬럼-커스터마이징-column-selector" aria-label="Permalink to &quot;📋 컬럼 커스터마이징 (Column Selector)&quot;">​</a></h3><ul><li>테이블 우측 상단의 컬럼 설정 메뉴를 통해 화면에 표출할 속성(우선순위, 담당자, 시작일, 완료기한, 진척도, 목표 버전 등)을 자유롭게 켜고 끌 수 있습니다.</li></ul><h3 id="💾-저장된-쿼리-saved-queries" tabindex="-1">💾 저장된 쿼리 (Saved Queries) <a class="header-anchor" href="#💾-저장된-쿼리-saved-queries" aria-label="Permalink to &quot;💾 저장된 쿼리 (Saved Queries)&quot;">​</a></h3><ul><li>자주 사용하는 검색 필터 조건(예: <em>&quot;나에게 할당된 긴급 결함&quot;</em>, <em>&quot;이번 달 목표 업무&quot;</em>)을 이름 붙여 사이드바에 저장하고 원클릭으로 재호출할 수 있습니다.</li></ul><h2 id="_3-업무-등록-및-주요-속성" tabindex="-1">3. 업무 등록 및 주요 속성 <a class="header-anchor" href="#_3-업무-등록-및-주요-속성" aria-label="Permalink to &quot;3. 업무 등록 및 주요 속성&quot;">​</a></h2><p>새로운 업무를 생성할 때는 명확한 협업 기준을 마련하기 위해 다음 항목들을 정의합니다.</p><ul><li><strong>업무 유형(Tracker)</strong>: <code>결함</code>, <code>기능</code>, <code>지원</code> 등 작업의 성격을 분류합니다.</li><li><strong>제목 및 마크다운(Markdown) 설명</strong>: 업무 목표와 상세 지침을 작성하며, 코드 블록, 테이블, 체크리스트 서식을 지원합니다.</li><li><strong>우선순위</strong>: <code>낮음</code>, <code>보통</code>, <code>높음</code>, <code>긴급</code> 4단계로 구분하여 작업의 시급성을 전달합니다.</li><li><strong>일정 및 기한 관리</strong>: <ul><li>시작일과 완료 기한을 지정하며, <strong>기한이 경과된 미완료 업무는 목록에서 붉은색으로 강조</strong>되어 지연을 방지합니다.</li></ul></li><li><strong>진척도(Done Ratio %)</strong>: 0%부터 100%까지 10% 단위로 완료율을 입력합니다.</li><li><strong>공유자(Watchers)</strong>: 담당자는 아니지만 해당 업무의 변경 사항과 댓글 알림을 실시간 이메일/모바일 푸시로 받아볼 팀원을 추가합니다.</li><li><strong>비공개 설정(<code>is_private</code>)</strong>: 체크 시 작성자, 담당자 및 관리자만 열람할 수 있도록 권한이 격리됩니다.</li></ul><h2 id="_4-구조화된-업무-협업-및-상세-보기" tabindex="-1">4. 구조화된 업무 협업 및 상세 보기 <a class="header-anchor" href="#_4-구조화된-업무-협업-및-상세-보기" aria-label="Permalink to &quot;4. 구조화된 업무 협업 및 상세 보기&quot;">​</a></h2><p>업무 상세 화면은 작업의 모든 히스토리와 산출물이 모이는 중심 허브입니다.</p><h3 id="🌲-하위-업무-sub-tasks-진척도-자동-롤업" tabindex="-1">🌲 하위 업무(Sub-tasks) &amp; 진척도 자동 롤업 <a class="header-anchor" href="#🌲-하위-업무-sub-tasks-진척도-자동-롤업" aria-label="Permalink to &quot;🌲 하위 업무(Sub-tasks) &amp; 진척도 자동 롤업&quot;">​</a></h3><ul><li>규모가 큰 업무는 여러 개의 하위 업무로 세분화하여 각기 다른 담당자를 지정할 수 있습니다.</li><li><strong>진척도 자동 계산</strong>: 하위 업무들의 진척률이 변경되면 <strong>상위 업무의 완료율(<code>Done Ratio</code>)이 평균값으로 자동 롤업 계산</strong>됩니다.</li></ul><h3 id="⛓️-선후행-연관-관계-issue-relations" tabindex="-1">⛓️ 선후행 연관 관계 (Issue Relations) <a class="header-anchor" href="#⛓️-선후행-연관-관계-issue-relations" aria-label="Permalink to &quot;⛓️ 선후행 연관 관계 (Issue Relations)&quot;">​</a></h3><ul><li>업무 간의 인과 관계를 설정하여 작업 순서를 명확히 합니다: <ul><li><strong>선행(Precedes) / 후행(Follows)</strong>: A 업무가 끝나야 B 업무가 시작될 수 있는 일정 종속 관계</li><li><strong>관련됨(Relates to)</strong>: 맥락상 참고가 필요한 참조 관계</li><li><strong>중복됨(Duplicates)</strong>: 동일한 이슈로 통합 처리되는 관계</li></ul></li></ul><h3 id="📝-회의록-meeting-자동-매핑" tabindex="-1">📝 회의록(Meeting) 자동 매핑 <a class="header-anchor" href="#📝-회의록-meeting-자동-매핑" aria-label="Permalink to &quot;📝 회의록(Meeting) 자동 매핑&quot;">​</a></h3><ul><li><a href="/work-manage/meeting.html">회의록</a>에서 도출된 액션 아이템으로 발행된 업무는 상단에 회의록 링크 배지가 자동 연결되어, 의사결정의 배경과 회의 맥락을 즉시 열람할 수 있습니다.</li></ul><h3 id="⏱️-변경-이력-3분할-탭-및-diff-지원" tabindex="-1">⏱️ 변경 이력 3분할 탭 및 Diff 지원 <a class="header-anchor" href="#⏱️-변경-이력-3분할-탭-및-diff-지원" aria-label="Permalink to &quot;⏱️ 변경 이력 3분할 탭 및 Diff 지원&quot;">​</a></h3><p>상세 화면 하단에서 업무와 관련된 모든 변경 기록을 3개 탭으로 나누어 검토할 수 있습니다:</p><ol><li><strong>전체로그</strong>: 댓글과 모든 항목 변경 히스토리를 시간 순으로 통합 표시</li><li><strong>댓글</strong>: 팀원들이 남긴 코멘트와 첨부 파일만 모아보기</li><li><strong>항목 변경이력</strong>: 상태 변경, 담당자 이관, 그리고 본문 수정 시 <strong>이전 텍스트와의 시각적 차이점(Diff)</strong> 확인</li></ol><h2 id="_5-다차원-업무-보고서-report" tabindex="-1">5. 다차원 업무 보고서 (Report) <a class="header-anchor" href="#_5-다차원-업무-보고서-report" aria-label="Permalink to &quot;5. 다차원 업무 보고서 (Report)&quot;">​</a></h2><p>워크스페이스 내 <strong>[업무] &gt; [보고서]</strong> 탭을 통해 프로젝트의 건전성을 다각도로 진단합니다.</p><ul><li><strong>매트릭스 통계</strong>: 담당자별, 유형(트래커)별, 목표 단계별, 우선순위별로 열린 업무와 닫힌 업무의 비율을 표와 차트로 한눈에 비교합니다.</li><li><strong>업무 부하량 모니터링</strong>: 특정 담당자에게 업무가 과도하게 집중되어 있는지 점검하고 자원 재배치를 결정할 수 있습니다.</li></ul>',25))])}const b=s(E,[["render",h]]);export{p as __pageData,b as default};
